npx tsc --noEmit && echo TSC_OK

cat > src/App.tsx <<'EOF'
import '@gravity-ui/page-constructor/styles/styles.scss';
import './global.css';

import { PageConstructor, PageConstructorProvider, Theme } from '@gravity-ui/page-constructor';
import { useThemeValue } from '@gravity-ui/uikit';

import { landingContent } from './content';

export function App() {
  // Keep page-constructor's themed values in sync with the uikit ThemeProvider.
  const themeValue = useThemeValue();
  const theme = themeValue.startsWith('dark') ? Theme.Dark : Theme.Light;

  return (
    <PageConstructorProvider theme={theme}>
      <PageConstructor content={landingContent} />
    </PageConstructorProvider>
  );
}
EOF
npm run build 2>&1 | tail -15

cat > vite.config.ts <<'EOF'
import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';
import dynamicImport from 'vite-plugin-dynamic-import';

export default defineConfig({
  resolve: {
    // page-constructor's SCSS uses webpack-style `~@gravity-ui/...` imports.
    alias: [{ find: /^~(@gravity-ui\/.*)$/, replacement: '$1' }],
  },
  plugins: [
    react(),
    // page-constructor loads blocks via dynamic imports, which Vite needs this plugin for.
    dynamicImport({
      filter: (id) => id.includes('/node_modules/@gravity-ui/page-constructor'),
    }),
  ],
});
EOF
